#!/usr/bin/env python3
"""Small executable DOM contract check for the paired-review browser code."""
from pathlib import Path
import json, re, subprocess, sys

ROOT = Path(__file__).parent
src = (ROOT / "static/index.html").read_text()
start = src.index("// --- Paired review ---")
end = src.index("// --- Review tab ---", start)
paired = src[start:end]
for name in ("trEpoch", "trPick", "trLoadFrames", "trReopen", "trSaveExample", "trLoadSaved", "trCalibrationReady"):
    assert len(re.findall(r"(?:const " + name + r"\s*=|(?:async )?function " + name + r"\s*\()", paired)) == 1, name

js = r'''
const ids = ['tr-site','tr-day','tr-cam-a','tr-cam-b','tr-mode','tr-time','tr-range','tr-delta','tr-save','tr-cal-save','transition-state','tr-canvas-a','tr-canvas-b','tr-meta-a','tr-meta-b','tr-side','tr-box-mode','tr-x','tr-y','tr-w','tr-h','tr-vis-a','tr-vis-b','tr-verdict','tr-journey','tr-title','tr-example','tr-reopen','tr-delete','tr-res','tr-calibration','tr-cal-load','tr-clear','tr-refresh','tr-time-minus','tr-time-plus','tr-time-01m','tr-time-01p','tr-time-1m','tr-time-1p','tr-full-zone'];
let clears=0, revoked=[]; const els = Object.fromEntries(ids.map(id => [id, {id, value:'', disabled:false, innerHTML:'', textContent:'', dataset:{}, options:[], appendChild(o){this.options.push(o)}, addEventListener(){}, getContext(){return {clearRect(){clears++},drawImage(){},strokeRect(){}}}, getBoundingClientRect(){return {left:0,top:0,width:100,height:100}}, setPointerCapture(){}}]));
els['tr-mode'].value='overlap'; els['tr-delta'].value='0'; els['tr-verdict'].value='same'; els['tr-vis-a'].value='full'; els['tr-vis-b'].value='partial';
globalThis.document={getElementById:id=>els[id], createElement:()=>({}), querySelectorAll:()=>[]};
globalThis.addEventListener=()=>{}; globalThis.Image=class {constructor(){this.complete=true;this.naturalWidth=100;this.naturalHeight=50;} set src(v){this._src=v; queueMicrotask(()=>this.onload&&this.onload());}};
const NativeURL=URL; URL.createObjectURL=()=>`blob:${Math.random()}`; URL.revokeObjectURL=u=>revoked.push(u);
globalThis.localStorage={}; globalThis.curation=true; globalThis.labTok='token-123';
const calls=[]; let deferred=[], catalogWait=[], listWait=[], reopenWait=[];
globalThis.fetch=(url, opts={})=>{calls.push({url:String(url),opts}); if(String(url).includes('/examples/ex1/frames/')) return Promise.resolve({ok:true,blob:async()=>new Blob(['jpeg'])}); if(String(url).includes('/frames')) return new Promise(resolve=>deferred.push(resolve)); if(String(url).endsWith('/recordings')) return new Promise(resolve=>catalogWait.push(resolve)); if(String(url).includes('/examples/ex1')) return new Promise(resolve=>reopenWait.push(resolve)); if(String(url).includes('/examples')) return new Promise(resolve=>listWait.push(resolve)); return Promise.resolve({ok:true,json:async()=>({examples:[]})});};
const labHdr=()=>({'X-Curator-Token':labTok});
const labFetch=(url)=>fetch(url,{headers:labHdr()});
''' + paired + r'''
function ok(x,m){if(!x)throw Error(m)}
ok(normalizeTransitionRect({x:.9,y:.9,width:.2,height:.1})===null,'clamp bounds');
let r=transitionRectFromPoints({x:.8,y:.7},{x:.2,y:.1}); ok(Math.abs(r.x-.2)<1e-9&&Math.abs(r.y-.1)<1e-9&&Math.abs(r.width-.6)<1e-9&&Math.abs(r.height-.6)<1e-9,'reverse geometry');
ok(Math.abs(trEpoch(trLocal(1788425617.85))-1788425617.85)<.001,'Lusaka time roundtrip');ok(trLocal(1788425617.85).startsWith('2026-09-03'),'September date is not month-shifted');ok(Number.isNaN(trEpoch('2026-02-30 12:00:00.000 +0200')),'invalid calendar date rejected');
TR.catalog={sites:['site1','site2'],recordings:[{key:'site1/cam1/d1.mkv',site:'site1',camera_id:'cam1',filename:'d1.mkv',start_ts:100},{key:'site1/cam2/d1.mkv',site:'site1',camera_id:'cam2',filename:'d1.mkv',start_ts:104},{key:'site1/cam3/d1.mkv',site:'site1',camera_id:'cam3',filename:'d1.mkv',start_ts:300},{key:'site1/cam1/d2.mkv',site:'site1',camera_id:'cam1',filename:'d2.mkv',start_ts:86400},{key:'site1/cam2/d2.mkv',site:'site1',camera_id:'cam2',filename:'d2.mkv',start_ts:86420},{key:'site2/cam9/d1.mkv',site:'site2',camera_id:'cam9',filename:'d1.mkv',start_ts:100}]};TR.site='site1';TR.date='1970-01-01';const realContext=trContextChanged;trContextChanged=()=>{};TR.sourceKeys=['',''];trPick();ok(els['tr-day'].options.some(o=>o.value==='1970-01-02'),'all selected-site dates preserved');ok(TR.rows.every(x=>x.site==='site1'&&x.key.includes('d1')),'sources restricted to chosen day');ok(Math.abs(TR.rows.find(x=>x.key===TR.sourceKeys[0]).start_ts-TR.rows.find(x=>x.key===TR.sourceKeys[1]).start_ts)===4,'nearest distinct-camera starts chosen');TR.date='1970-01-02';trPick();ok(TR.rows.every(x=>x.key.includes('d2')),'second date sources consistent');TR.site='site2';TR.date='1970-01-01';trPick();ok(TR.rows.every(x=>x.site==='site2'),'site change sources consistent');TR.site='site1';TR.date='1970-01-01';TR.sourceKeys=['site1/cam1/d1.mkv','site1/cam2/d1.mkv'];els['tr-cam-a'].value=TR.sourceKeys[0];els['tr-cam-b'].value=TR.sourceKeys[1];trPick();ok(TR.sourceKeys[0].startsWith('site1/'),'site A restored');trContextChanged=realContext;els['tr-cam-a'].value='site1/cam1/d1.mkv';els['tr-cam-b'].value='site1/cam2/d1.mkv';TR.sourceKeys=[els['tr-cam-a'].value,els['tr-cam-b'].value];
TR.ts=10; trLoadFrames(true); ok(calls.at(-1).opts.headers['X-Curator-Token']==='token-123','auth header'); let u=new NativeURL(calls.at(-1).url,'http://x'); ok(u.searchParams.get('source_a')==='site1/cam1/d1.mkv'&&u.searchParams.get('source_b')==='site1/cam2/d1.mkv'&&u.searchParams.get('ts')==='10','frame query');
trBind();TR.ts=10;els['tr-delta'].value='5';els['tr-delta'].oninput();els['tr-delta'].onchange();const deltaCall=calls.at(-1),deltaUrl=new NativeURL(deltaCall.url,'http://x');ok(deltaUrl.searchParams.get('ts')==='10'&&deltaUrl.searchParams.get('delta_s')==='5','delta change preserves exact ts');const deltaDeferred=deferred.pop();const old=deferred.shift(); els['tr-cam-a'].value='site1/cam2/d1.mkv'; els['tr-cam-b'].value='site1/cam1/d1.mkv'; TR.sourceKeys=[els['tr-cam-a'].value,els['tr-cam-b'].value]; trContextChanged(true); const newer=deferred.shift(); old({ok:true,json:async()=>({ts:1,interval:[1,2],frames:[]})}); newer({ok:true,json:async()=>({ts:2,interval:[2,3],frames:[{side:'a',source_key:TR.sourceKeys[0],requested_ts:2,camera_id:'cam2',jpeg_data_url:'a',width:100,height:50,jpeg_sha256:'a'.repeat(64),offset_known:false},{side:'b',source_key:TR.sourceKeys[1],requested_ts:2,camera_id:'cam1',jpeg_data_url:'b',width:100,height:50,jpeg_sha256:'b'.repeat(64),offset_known:true}]})});
setTimeout(async()=>{ok(TR.ts===2,'stale context response overwrote newest');ok(transitionPayload({verdict:'same',views:[{side:'a',visibility:'full',bbox:{x:0,y:0,width:.2,height:.2},jpeg_sha256:'a'.repeat(64)},{side:'b',visibility:'partial',bbox:{x:0,y:0,width:.2,height:.2},jpeg_sha256:'b'.repeat(64)}]}),'full partial validation');ok(!transitionPayload({verdict:'same',views:[{side:'a',visibility:'occluded',bbox:null,jpeg_sha256:'a'.repeat(64)},{side:'b',visibility:'occluded',bbox:null,jpeg_sha256:'b'.repeat(64)}]}),'both occluded requires uncertain');trBind();TR.boxes.a.vehicle={x:0,y:0,width:.2,height:.2};els['tr-range'].min=10;els['tr-range'].max=20;els['tr-range'].value=12;els['tr-range'].disabled=false;els['tr-range'].oninput({target:els['tr-range']});ok(!els['tr-range'].disabled&&els['tr-range'].min===10&&els['tr-range'].max===20&&!TR.boxes.a.vehicle&&els['tr-save'].disabled,'range input preserves bounds and clears old vehicle');const c0=clears;TR.urls.push('blob:old');trReset();deltaDeferred({ok:true,json:async()=>({ts:99,interval:[99,100],frames:[]})});ok(clears>c0&&revoked.includes('blob:old'),'reset clears canvas and revokes URLs');TR.catalog=null;trCatalog(true);const cat=catalogWait.shift();trReset();cat({ok:true,json:async()=>({sites:['stale'],recordings:[]})});await Promise.resolve();ok(TR.catalog===null&&els['tr-site'].innerHTML==='','stale catalog cannot repaint after reset');TR.site='site1';TR.date='1970-01-01';trLoadSaved();const lst=listWait.shift();trReset();lst({ok:true,json:async()=>({examples:[{id:'other'}]})});await Promise.resolve();ok(els['tr-example'].innerHTML==='','stale saved list cannot repaint after reset');TR.calibrations=[{id:'cal1',camera_ids:['cam1','cam2'],mode:'overlap',delta_s:.25,title:'saved cal',zones:[{x:0,y:0,width:.5,height:.5},{x:.5,y:.5,width:.4,height:.4}]}];TR.saved=[];TR.catalog={recordings:[{key:'site1/cam1/d1.mkv',site:'site1',camera_id:'cam1',filename:'d1.mkv',start_ts:100},{key:'site1/cam2/d1.mkv',site:'site1',camera_id:'cam2',filename:'d1.mkv',start_ts:104}]};TR.site='site1';TR.date='1970-01-01';TR.rows=trSelectedRows();els['tr-cam-a'].value='site1/cam2/d1.mkv';els['tr-cam-b'].value='site1/cam1/d1.mkv';const oldCtx=trContextChanged;trContextChanged=()=>{};els['tr-calibration'].value='cal1';trLoadCalibration();ok(els['tr-cam-a'].value==='site1/cam1/d1.mkv'&&TR.boxes.a.zone.width===.5,'ordered calibration load with no examples');trContextChanged=oldCtx;els['tr-example'].value='ex1';const rp=trReopen();const rr=reopenWait.shift();rr({ok:true,json:async()=>({id:'ex1',calibration_id:'cal1',source_keys:['site1/cam1/d1.mkv','site1/cam2/d1.mkv'],ts:12,interval:[10,20],journey_label:'journey',verdict:'same',views:[{side:'a',visibility:'full',bbox:{x:0,y:0,width:.2,height:.2}},{side:'b',visibility:'partial',bbox:{x:.2,y:.2,width:.2,height:.2}}],frames:[{side:'a',camera_id:'cam1',source_filename:'d1.mkv',requested_ts:12,corrected_ts:12,offset_known:false,jpeg_url:'/api/dataset/paired/site1/1970-01-01/examples/ex1/frames/a',jpeg_sha256:'a'.repeat(64)},{side:'b',camera_id:'cam2',source_filename:'d1.mkv',requested_ts:12.25,corrected_ts:12.25,offset_known:true,jpeg_url:'/api/dataset/paired/site1/1970-01-01/examples/ex1/frames/b',jpeg_sha256:'b'.repeat(64)}]})});await rp;ok(els['tr-range'].disabled===false&&els['tr-meta-a'].textContent.includes('camera clock offset unknown'),'reopen restores unknown notice and range');console.log('paired DOM checks passed')},0);
'''

if __name__ == "__main__":
    p = subprocess.run(["node", "-e", js], text=True, capture_output=True)
    sys.stdout.write(p.stdout)
    sys.stderr.write(p.stderr)
    raise SystemExit(p.returncode)
